    batch_no, pay_channel, reconcile_date, total_transactions,
    matched_transactions, mismatched_transactions, total_amount_vnd, status
) VALUES (
    #{batchNo}, #{payChannel}, #{reconcileDate}, #{totalTransactions},
    #{matchedTransactions}, #{mismatchedTransactions}, #{totalAmountVnd}, #{status}
)

INSERT INTO bank_reconciliation_item (
    batch_id, out_trade_no, bank_trade_no, amount_vnd, match_status, discrepancy_reason
) VALUES (
    #{batchId}, #{outTradeNo}, #{bankTradeNo}, #{amountVnd}, #{matchStatus}, #{discrepancyReason}
)

